import{_ as e,o as t,c as o,a2 as n}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"What can OrbySystems do?","description":"","frontmatter":{"title":"What can OrbySystems do?"},"headers":[],"relativePath":"docs/overview/what-can-orby-do.md","filePath":"docs/overview/what-can-orby-do.md","lastUpdated":1790284433000}'),r={name:"docs/overview/what-can-orby-do.md"};function s(i,a,l,d,c,h){return t(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="what-can-orbysystems-do" tabindex="-1">What can OrbySystems do? <a class="header-anchor" href="#what-can-orbysystems-do" aria-label="Permalink to &quot;What can OrbySystems do?&quot;">​</a></h1><h2 id="chat-over-your-data" tabindex="-1">Chat over your data <a class="header-anchor" href="#chat-over-your-data" aria-label="Permalink to &quot;Chat over your data&quot;">​</a></h2><p>Ask questions in plain language and get answers grounded in your actual data — plain text, a data table, or a chart, whichever fits the question best.</p><h2 id="personal-finance-end-to-end" tabindex="-1">Personal finance, end to end <a class="header-anchor" href="#personal-finance-end-to-end" aria-label="Permalink to &quot;Personal finance, end to end&quot;">​</a></h2><ul><li><strong>Spending &amp; income</strong> — every transaction auto-categorized, with recipes for spending trends, recurring bills, top merchants, and more.</li><li><strong>Investment</strong> — track brokerage holdings, allocation, and performance.</li><li><strong>Assets &amp; liabilities</strong> — manually track a house, a car, or other assets, plus the loans against them, with automatic principal/interest tracking on linked payments.</li><li><strong>Combined finance</strong> — bring everything together into one net worth and debt picture across all your accounts.</li></ul><p>See the <a href="/docs/personal-finance/types-of-finance-projects">Personal Finance</a> section for details.</p><h2 id="recipes-and-dashboards" tabindex="-1">Recipes and dashboards <a class="header-anchor" href="#recipes-and-dashboards" aria-label="Permalink to &quot;Recipes and dashboards&quot;">​</a></h2><p>Pre-built charts and breakdowns for the questions you&#39;ll ask often, with drill-downs into the details behind any number. See <a href="/docs/getting-started/browse-recipes">Browse Recipes</a>.</p><h2 id="getting-your-data-in" tabindex="-1">Getting your data in <a class="header-anchor" href="#getting-your-data-in" aria-label="Permalink to &quot;Getting your data in&quot;">​</a></h2><ul><li><strong>Statement Downloader</strong> — automatically fetch statements from supported institutions instead of downloading them by hand.</li><li><strong>Statement Downloader Builder</strong> — walk through building support for a new institution yourself.</li><li><strong>Transactions Extractor</strong> — parses bank and brokerage statements (PDF, CSV, spreadsheet) into clean transaction data.</li><li><strong>Transactions Extractor Builder</strong> — teach OrbySystems to understand a statement format it doesn&#39;t already recognize.</li></ul><h2 id="privacy-tools" tabindex="-1">Privacy tools <a class="header-anchor" href="#privacy-tools" aria-label="Permalink to &quot;Privacy tools&quot;">​</a></h2><ul><li><strong>PII Redactor</strong> — strip personal information out of a document before sharing or saving it elsewhere.</li><li><strong>PII Detector</strong> — scan a document to see what personal information it contains, without modifying it.</li></ul><h2 id="working-with-documents" tabindex="-1">Working with documents <a class="header-anchor" href="#working-with-documents" aria-label="Permalink to &quot;Working with documents&quot;">​</a></h2><ul><li><strong>Document Chunker</strong> — break a large document into pieces ready for OrbySystems to work with.</li></ul><h2 id="model-tools" tabindex="-1">Model tools <a class="header-anchor" href="#model-tools" aria-label="Permalink to &quot;Model tools&quot;">​</a></h2><ul><li><strong>Model Test</strong> — check that a model you&#39;ve configured works correctly with OrbySystems.</li><li><strong>Model Eval Suite</strong> — measure how well and how fast a given model answers real finance questions, so you can choose with confidence.</li></ul><p>See the <a href="/docs/tools/statement-downloader">Tools</a> section for a full walkthrough of each.</p>',17)])])}const m=e(r,[["render",s]]);export{g as __pageData,m as default};
